function stepTimer(state, event) {
  const next = { ...state };
  const type = typeof event === 'string' ? event : event?.type;

  switch (type) {
    case 'start':
      next.status = next.remaining > 0 ? 'running' : 'done';
      break;
    case 'pause':
      if (next.status === 'running') next.status = 'paused';
      break;
    case 'reset':
      next.remaining = next.duration;
      next.status = 'idle';
      break;
    case 'tick':
      if (next.status === 'running') {
        next.remaining = Math.max(0, next.remaining - event.seconds);
        if (next.remaining === 0) next.status = 'done';
      }
      break;
  }

  return next;
}
